mapper.select:
SELECT id,name,status,total_stock,issued_count,valid_start_at,valid_end_at,rule_json,version,created_at,updated_at
FROM coupon_template

    AND status=#{status}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
FROM coupon_instance i
JOIN coupon_template t ON t.id=i.coupon_template_id

    AND i.coupon_template_id=#{templateId}
    AND i.status=#{status}
    AND i.order_id=#{orderId}
    AND i.created_at>=#{createdFrom}
    AND i.created_at<=#{createdTo}

mapper.update:
UPDATE coupon_template
SET status=#{toStatus}, version=version + 1, updated_at=#{now}
WHERE id=#{templateId} AND status=#{fromStatus} AND version=#{expectedVersion}

mapper.select:
SELECT COUNT(*) FROM coupon_instance
WHERE coupon_template_id=#{templateId} AND user_id=#{userId}
  AND status IN ('AVAILABLE','FROZEN')

SELECT COUNT(*)
FROM coupon_ledger l
JOIN coupon_instance i ON i.id = l.coupon_instance_id
WHERE l.action='ISSUE'
  AND i.coupon_template_id=#{templateId}
  AND l.user_id=#{userId}
  AND l.remark LIKE CONCAT('operator=', #{operatorId}, ';%')
  AND l.created_at > #{since}

mapper.update:
UPDATE coupon_template
SET issued_count = issued_count + 1, updated_at=#{now}
WHERE id=#{templateId} AND (total_stock IS NULL OR issued_count < total_stock)

UPDATE coupon_instance
SET status='VOID', version=version + 1, updated_at=#{now}
WHERE id=#{instanceId} AND status='AVAILABLE'

mapper.select:
SELECT 
FROM coupon_campaign c
INNER JOIN coupon_template t ON t.id=c.template_id

    AND c.status=#{status}

ORDER BY c.created_at DESC, c.id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE coupon_campaign
SET name=#{name}, template_id=#{templateId}, audience_type=#{audienceType},
    per_user_limit=#{perUserLimit}, total_limit=#{totalLimit}, budget_limit=#{budgetLimit},
    start_at=#{startAt}, end_at=#{endAt}, version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status=#{toStatus}, version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND status=#{fromStatus} AND version=#{expectedVersion}

UPDATE coupon_campaign
SET issued_count=issued_count+1,
    issued_amount=issued_amount+#{amountOff},
    updated_at=#{now}
WHERE id=#{campaignId}
  AND status IN ('ACTIVE','SCHEDULED')
  AND start_at <= #{now} AND end_at > #{now}
  AND issued_count < total_limit
  AND issued_amount + #{amountOff} <= budget_limit

mapper.select:
SELECT id,campaign_id,user_id,coupon_instance_id,claimed_at,request_id
FROM coupon_claim
WHERE campaign_id=#{campaignId}
ORDER BY claimed_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id,campaign_id,user_id,coupon_instance_id,claimed_at,request_id
FROM coupon_claim
WHERE campaign_id=#{campaignId} AND user_id=#{userId}

SELECT id,campaign_id,user_id,coupon_instance_id,claimed_at,request_id
FROM coupon_claim
WHERE request_id=#{requestId}
